package dev.atqiya.ledgerly.invoicing.domain;
import static org.junit.jupiter.api.Assertions.*; import dev.atqiya.ledgerly.identity.domain.AppUser; import dev.atqiya.ledgerly.workspace.domain.Workspace; import java.math.BigDecimal; import java.time.*; import java.util.UUID; import org.junit.jupiter.api.Test;
class InvoiceTest{
 private final Instant now=Instant.parse("2026-10-09T00:00:00Z"); private final AppUser user=new AppUser(UUID.randomUUID(),"owner@test.dev","Owner","hash",now); private final Workspace workspace=new Workspace(UUID.randomUUID(),"Studio","studio","IDR","Asia/Jakarta",user,now); private final Customer customer=new Customer(UUID.randomUUID(),workspace,"Client",null,null,null,user,now);
 @Test void calculatesTotalsAndCompletesPaymentLifecycle(){Invoice invoice=new Invoice(UUID.randomUUID(),workspace,customer,"INV-001",LocalDate.parse("2026-10-01"),LocalDate.parse("2026-10-15"),null,user,now);invoice.addLine("Design",new BigDecimal("2"),new BigDecimal("125000.50"));assertEquals(new BigDecimal("250001.0000"),invoice.getTotal());invoice.send(user,now.plusSeconds(1));invoice.recordPayment(new BigDecimal("100001.0000"),user,now.plusSeconds(2));assertEquals(InvoiceStatus.SENT,invoice.getStatus());invoice.recordPayment(new BigDecimal("150000.0000"),user,now.plusSeconds(3));assertEquals(InvoiceStatus.PAID,invoice.getStatus());assertEquals(0,invoice.getOutstanding().compareTo(BigDecimal.ZERO));}
 @Test void rejectsOverpaymentAndDetectsOverdue(){Invoice invoice=new Invoice(UUID.randomUUID(),workspace,customer,"INV-002",LocalDate.parse("2026-09-01"),LocalDate.parse("2026-09-15"),null,user,now);invoice.addLine("Service",BigDecimal.ONE,new BigDecimal("100"));invoice.send(user,now);assertTrue(invoice.isOverdue(LocalDate.parse("2026-10-09")));assertThrows(IllegalStateException.class,()->invoice.recordPayment(new BigDecimal("101"),user,now));}
}
